/* V0.7: quick registration and linked updates. */
(function(){
const prev={action,render,detail};
const kinds={budget:'预算',quote:'报价',contract:'合同',receipt:'回款',reference:'参考'},bases={annual:'万元/年',monthly:'万元/月',total:'万元总额'};
const rows=p=>data.ledger.filter(r=>r.pid===p.id&&!r.voided);
const amount=r=>`${(r.cents/1000000).toLocaleString('zh-CN',{maximumFractionDigits:6})} ${bases[r.basis]}`;
function audit(a,pid,detail){data.audit.push({id:id(),at:new Date().toISOString(),action:a,pid,detail})}
function opt(label,key,body){return `<details class="update-option field full" data-section="${key}"><summary>＋ ${label}</summary><div class="fields">${body}</div></details>`}
function quickNew(){modal('快速登记项目',`<div class="field full quick-intro">先记下来，其他信息随项目推进再补充。</div>`+field('项目名称 *','name')+field('客户单位 *','unit')+area('一句话背景 / 需求（选填）','background')+select('当前阶段','stage',stages.filter(s=>s!=='历史未知'))+opt('补充信息','extra',field('负责人','owner','text','我')+field('登记日期','date','date',today())+select('所属行业','bu',['其他','医卫','党政','金融','教育','企业'])+field('业务类型','type')),v=>{if(!v.date||v.date>today())throw Error('登记日期不能晚于今天');const p={...v,id:id(),createdDate:v.date,owner:v.owner||'我',events:[],quotes:[],competitors:[],files:[],archiveHistory:[],stageHistory:[{id:id(),date:v.date,stage:v.stage,recordedAt:new Date().toISOString(),source:'初次登记'}],amount:null,basis:'金额待确认',confirmed:false,starred:false};data.projects.unshift(p);audit('新建项目',p.id,p.name);selected=p.id;tab='概览'},{drawer:true});}
function update(pid=selected,section){const ps=data.projects.filter(p=>!p.archived);if(!ps.length)return quickNew();pid=pid||ps[0].id;let files=[];const fieldset=select('关联项目','pid',[[pid,getp(pid).name],...ps.filter(p=>p.id!==pid).map(p=>[p.id,p.name])])+area('今天有什么新进展？ *','body')+opt('涉及金额','money',select('金额类型','kind',[['budget','预算'],['quote','报价'],['contract','合同签约'],['receipt','实际回款']])+field('金额（万元）','value','number')+select('金额口径','basis',[['total','全周期总额'],['annual','年度服务费'],['monthly','月度服务费']])+select('金额确认状态','confirmed',[['no','待确认'],['yes','已确认']])+select('关联合同（回款必选）','contractId',[['','请选择'],...data.ledger.filter(r=>r.kind==='contract'&&r.confirmed&&!r.voided).map(r=>[r.id,getp(r.pid)?.name+' / '+r.title])]))+opt('涉及竞争','competition',field('竞争方名称','competitor')+area('竞争信息 / 我方应对','competition')+select('竞争信息状态','competitionStatus',['待核实','已确认']))+opt('添加资料','files',`<label class="field full">选择本机文件<input type="file" id="update-files" multiple><small>本 Demo 仅登记文件名称与大小，原件仍在本机，不上传正文。</small></label>`)+opt('安排下一步','task',field('下一步行动','next')+field('截止 / 预计反馈日期','due','date',today())+select('行动状态','state',[['action','待我处理'],['customer','等待客户'],['internal','等待内部']])+field('跟进接口人','contact'))+opt('日期、来源与阶段','context',field('发生日期','date','date',today())+field('资料来源','source','text','手工记录')+select('更新项目阶段','stage',['保持当前阶段',...stages.filter(s=>s!=='历史未知')]));
modal('记一次更新',fieldset,v=>{const p=getp(v.pid),on=k=>document.querySelector(`[data-section="${k}"]`)?.open;if(!v.body.trim())throw Error('请填写本次进展');if(!v.date||v.date<created(p)||v.date>today())throw Error('发生日期须在登记日期与今天之间');let cents=null;if(on('money')){cents=YunchengV3.cents(v.value);if(cents<=0)throw Error('金额必须大于0');if(v.kind==='receipt'){const c=data.ledger.find(r=>r.id===v.contractId&&r.pid===p.id&&r.kind==='contract'&&r.confirmed&&!r.voided);if(!c||v.basis!=='total'||v.date<c.date)throw Error('回款须关联本项目有效合同，使用总额口径且日期不早于合同');}}if(on('competition')&&!v.competitor.trim())throw Error('请填写竞争方名称');if(on('files')&&!files.length)throw Error('请选择资料文件');if(on('task')){if(!v.next.trim()||!v.due||v.due<v.date)throw Error('请填写下一步行动和有效日期');if(v.state!=='action'&&!v.contact.trim())throw Error('等待事项请填写跟进接口人');}const e={id:id(),date:v.date,title:v.body.trim().split('\n')[0].slice(0,55),body:v.body,type:'项目更新',key:v.stage!=='保持当前阶段',source:v.source||'手工记录',recordedAt:new Date().toISOString()};p.events.push(e);if(on('money'))data.ledger.push({id:id(),pid:p.id,kind:v.kind,title:e.title,cents,basis:v.basis,date:v.date,confirmed:v.confirmed==='yes',source:e.source,sourceEvent:e.id,contractId:v.contractId||null});if(on('competition'))p.competitors.push({id:id(),name:v.competitor,product:'',strength:'',weakness:v.competition,strategy:'',status:v.competitionStatus,date:v.date,source:e.source,sourceEvent:e.id});if(on('files'))p.files.push(...files.map(f=>({...f,id:id(),date:v.date,sourceEvent:e.id})));if(on('task'))data.tasks.push({id:id(),pid:p.id,title:v.next,date:v.due,state:v.state,done:false,owner:p.owner||'我',contact:v.contact,sourceEvent:e.id,createdDate:today()});if(v.stage!=='保持当前阶段')p.stageHistory.push({id:id(),date:v.date,stage:v.stage,recordedAt:e.recordedAt,source:e.title});audit('统一更新',p.id,e.title);selected=p.id;tab='全部动态';},{drawer:true});document.querySelector('#update-files').onchange=e=>{files=Array.from(e.target.files).map(f=>({name:f.name,size:f.size}))};if(section)document.querySelector(`[data-section="${section}"]`).open=true;document.querySelectorAll('.update-option').forEach(d=>d.addEventListener('toggle',()=>{d.querySelector('summary').textContent=(d.open?'− ':'＋ ')+d.querySelector('summary').textContent.slice(2)}));}
function cards(p){const rs=rows(p),r=[...rs].filter(x=>x.kind!=='receipt').sort((a,b)=>b.date.localeCompare(a.date)).at(0);return `<div class="simple-cards">${[['金额','money',r?amount(r):'待确认',r?(kinds[r.kind]+' · '+(r.confirmed?'已确认':'待确认')):'有预算或报价时再补充'],['竞争情况','competition',p.competitors.length?p.competitors.at(-1).name:'暂未记录',p.competitors.length?p.competitors.at(-1).status:'未知不代表没有竞争'],['项目资料','files',(p.files?.length||0)+' 份资料','本 Demo 保存文件索引']].map(([label,k,value,hint])=>`<section class="panel simple-card"><span>${label}</span><h2>${esc(value)}</h2><p>${esc(hint)}</p><button class="link" data-records="${k}">查看全部 →</button><button class="link" data-update="${k}">＋ 补充</button></section>`).join('')}</div>`}
function dynamics(p){const rs=rows(p),items=p.events.map(e=>({date:e.date,at:e.recordedAt||'',title:e.title,body:e.body,source:e.source,event:e}));rs.filter(r=>!p.events.some(e=>e.id===r.sourceEvent)).forEach(r=>items.push({date:r.date,title:kinds[r.kind]+' · '+amount(r),body:r.title,source:r.source}));p.competitors.filter(c=>!p.events.some(e=>e.id===c.sourceEvent)).forEach(c=>items.push({date:c.date,title:'竞争信息 · '+c.name,body:[c.strength,c.weakness,c.strategy].filter(Boolean).join('\n'),source:c.source}));(p.files||[]).filter(f=>!p.events.some(e=>e.id===f.sourceEvent)).forEach(f=>items.push({date:f.date||created(p),title:'新增资料 · '+f.name,body:'文件索引，原件仍在本机'}));items.sort((a,b)=>b.date.localeCompare(a.date)||(b.at||'').localeCompare(a.at||''));return `<section class="panel simple-feed"><div class="panelhead"><h2>全部动态</h2><span class="muted small">一次记录，关联各项信息</span></div>${items.map(x=>`<article><time>${x.date}</time><h3>${esc(x.title)}</h3><p>${esc(x.body||'')}</p><div class="update-links">${x.event?rs.filter(r=>r.sourceEvent===x.event.id).map(r=>`<span>${kinds[r.kind]} · ${amount(r)} · ${r.confirmed?'已确认':'待确认'}</span>`).join('')+p.competitors.filter(c=>c.sourceEvent===x.event.id).map(c=>`<span>竞争 · ${esc(c.name)} · ${esc(c.status)}</span>`).join('')+(p.files||[]).filter(f=>f.sourceEvent===x.event.id).map(f=>`<span>资料 · ${esc(f.name)}</span>`).join('')+data.tasks.filter(t=>t.sourceEvent===x.event.id).map(t=>`<span>下一步 · ${esc(t.title)} · ${t.date}</span>`).join(''):''}</div><small>${esc(x.source||'来源未记录')}</small></article>`).join('')||'<div class="empty">项目已登记。发生新变化时，记一次更新即可。</div>'}</section>`}
detail=function(){const p=getp(selected),overview=['概览','项目概览'].includes(tab);let h=prev.detail();h=h.slice(0,h.indexOf('<div class="tabs">'));return h+`<div class="tabs"><button data-simple-tab="概览" class="${overview?'active':''}">项目概览</button><button data-simple-tab="全部动态" class="${!overview?'active':''}">全部动态</button></div>`+(overview?`<section class="panel simple-context"><span class="daily-eyebrow">PROJECT AT A GLANCE</span><h2>${esc(p.background||'先记录项目，需求可以逐步补充。')}</h2><p>${esc([...p.events].sort((a,b)=>b.date.localeCompare(a.date)||(b.recordedAt||'').localeCompare(a.recordedAt||''))[0]?.title||'尚未记录进展')}</p></section>`+cards(p)+`<div class="simple-next panel"><h2>下一步</h2>${data.tasks.filter(t=>t.pid===p.id&&!t.done).map(t=>`<p>${esc(t.title)} <small>${t.date}</small></p>`).join('')||'<p class="muted">暂未安排，记录更新时可一起添加。</p>'}</div>`:dynamics(p));};
function records(k){const p=getp(selected);let html='';if(k==='money')html=rows(p).map(r=>`<article><h3>${kinds[r.kind]} · ${amount(r)}</h3><p>${esc(r.title)}</p><small>${r.date} · ${r.confirmed?'已确认':'待确认'} · ${esc(r.source)}</small></article>`).join('');if(k==='competition')html=p.competitors.map(c=>`<article><h3>${esc(c.name)} · ${esc(c.status)}</h3><p>${esc([c.product,c.strength,c.weakness,c.strategy].filter(Boolean).join('\n'))}</p><small>${esc(c.date)} · ${esc(c.source||'来源待补充')}</small></article>`).join('');if(k==='files')html=(p.files||[]).map(f=>`<article><h3>${esc(f.name)}</h3><p>${Math.ceil(f.size/1024)} KB · 文件索引，原件仍在本机</p></article>`).join('');modal({money:'金额记录',competition:'竞争记录',files:'资料索引'}[k],`<div class="field full record-list">${html||'<p class="muted">暂未记录，可通过“记一次更新”补充。</p>'}</div>`,()=>{},{readonly:true,drawer:true});}
action=function(a){if(a==='new')return quickNew();if(a==='progress')return update();return prev.action(a)};
render=function(){prev.render();if(selected){const b=document.querySelector('[data-action="progress"]');if(b)b.textContent='＋ 记一次更新';document.querySelector('[data-action="task"]')?.remove();}document.querySelectorAll('[data-simple-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.simpleTab;render()});document.querySelectorAll('[data-update]').forEach(b=>b.onclick=()=>update(selected,b.dataset.update));document.querySelectorAll('[data-records]').forEach(b=>b.onclick=()=>records(b.dataset.records));document.querySelectorAll('[data-v6="capture"],[data-channel]').forEach(b=>{b.textContent=b.dataset.channel||'＋ 记一次更新';b.onclick=()=>update(null)});};
})();
